const __quietstartKits = {
"rewardVideo": (// The original reward-video business policy, with platform observation and
// geometry replaced by declared host-owned references. No screen/input APIs.
function createRewardVideoKit(spec) {
  if (!spec || !Number.isSafeInteger(spec.maxAds) || spec.maxAds < 1 || spec.maxAds > 300) {
    throw Error('invalid-reward-video-policy');
  }
  const enhanced = (spec.resumeAlternateTexts ?? []).length > 0;
  const compact = value => String(value ?? '').replace(/[\s\u200b\ufeff]/g, '');
  const copy = value => JSON.parse(JSON.stringify(value));
  const lines = frame => (frame?.lines ?? []).slice(0, 80);
  const hasLine = (frame, word) => compact(frame?.text).includes(compact(word)) ||
    lines(frame).some(line => compact(line.text).includes(compact(word)));
  const adBadgeVisible = frame => !!compact(spec.adBadgeText) && lines(frame).some(line => {
    const text = compact(line.text), badge = compact(spec.adBadgeText);
    return text.startsWith(badge) && text.length <= badge.length + 4;
  });
  const adCountdownVisible = frame => /\d+秒后可领取/.test(compact(frame?.text)) ||
    lines(frame).some(line => /\d+秒后可领取/.test(compact(line.text)));
  const fallbackId = typeof spec.closeFallbackQuery === 'string' ? spec.closeFallbackQuery : '';
  function fallbackEligible(frame, queries) {
    return !!fallbackId && frame?.ownerValid === true && adBadgeVisible(frame) && hasLine(frame, spec.adReadyText) &&
      !adCountdownVisible(frame) && !/\d+秒/.test(compact(frame?.text)) &&
      !lines(frame).some(line=>/\d+秒/.test(compact(line.text))) && !queries?.['close-image']?.matched && !lines(frame).some(line => {
        const text=compact(line.text);
        return spec.adCloseMarks.includes(text) && line.targets?.self || text.includes(compact(spec.adReadyText)) &&
          spec.adCloseMarks.some(mark=>text.endsWith(mark)) && line.targets?.tailSquare;
      });
  }

  function closeTarget(frame, queries) {
    if (frame?.ownerValid !== true || !adBadgeVisible(frame) || !hasLine(frame, spec.adReadyText) ||
      adCountdownVisible(frame)) return undefined;
    if (queries?.['close-image']?.matched && queries['close-image'].targetRef) {
      return { targetRef: queries['close-image'].targetRef, evidenceRefs: [frame.frameRef] };
    }
    const found = [];
    for (const line of lines(frame)) {
      const text = compact(line.text);
      if (spec.adCloseMarks.includes(text) && line.targets?.self) {
        found.push(line.targets.self); continue;
      }
      if (text.includes(compact(spec.adReadyText)) && spec.adCloseMarks.some(mark => text.endsWith(mark)) &&
        line.targets?.tailSquare) found.push(line.targets.tailSquare);
    }
    if (found.length === 1) return { targetRef: found[0] };
    if (found.length === 0 && fallbackEligible(frame, queries) && queries?.[fallbackId]?.matched && queries[fallbackId].targetRef)
      return {targetRef:queries[fallbackId].targetRef,fallback:true};
    return undefined;
  }
  function resumeTarget(frame) {
    if (frame?.ownerValid !== true || !hasLine(frame, spec.resumeContextText)) return undefined;
    const words = [spec.resumeNextText, ...(spec.resumeAlternateTexts ?? [])].map(compact);
    const found = lines(frame).filter(line => words.some(word => compact(line.text).includes(word)) && line.targets?.self);
    return found.length === 1 ? { targetRef: found[0].targets.self,
      openLabel: words.find(word => compact(found[0].text).includes(word)) } : undefined;
  }
  function nextTarget(frame, queries) {
    if (frame?.ownerValid !== true || !lines(frame).some(line => compact(line.text).includes(compact(spec.dialogContextText)))) {
      return undefined;
    }
    const found = lines(frame).filter(line => compact(line.text) === compact(spec.dialogNextText));
    if (found.length !== 1) return undefined;
    if (found[0].targets?.nativeOverlap) return { targetRef: found[0].targets.nativeOverlap };
    // Preserve V3's pixel-only fallback: an unrelated native Text receiver
    // inside this card vetoes the OCR target even when the OCR label is unique.
    if (!enhanced || !queries?.['dialog-text-exists'] || queries['dialog-text-exists'].matched ||
      !found[0].targets?.self) return undefined;
    return { targetRef: found[0].targets.self };
  }
  function initial(now) {
    return { phase: 'entry', phaseAt: now, nextReadAt: 0, adsClosed: 0,
      closePending: false, closeRetries: 0, done: false, reason: '', observationCount: 0,
      badgeCount: 0, readyCount: 0, countdownCount: 0, closeImageCount: 0, captureError: '', actionSequence: 0 };
  }
  function valid(s, now) {
    if (!s || !['entry', 'ad', 'dialog'].includes(s.phase) || !Number.isFinite(now) ||
      ['phaseAt', 'nextReadAt', 'adsClosed', 'closeRetries', 'observationCount', 'badgeCount',
        'readyCount', 'countdownCount', 'closeImageCount', 'actionSequence'].some(key =>
        !Number.isSafeInteger(s[key]) || s[key] < 0) ||
      ['closePending', 'done'].some(key => typeof s[key] !== 'boolean') ||
      ['reason', 'captureError'].some(key => typeof s[key] !== 'string')) throw Error('invalid-reward-video-checkpoint');
  }
  function result(checkpoint, outcome = 'waiting', intent, applied) {
    return { status: checkpoint.done ? 'complete' : 'running', checkpoint, outcome,
      ...(intent ? { intent } : {}), ...(applied ? { applied } : {}) };
  }
  function tap(s, target, outcome, applied) {
    const { openLabel, ...input } = target;
    if (outcome === 'next' || outcome === 'resume') {
      applied = { ...applied, pendingOpen: { kind: outcome, label: openLabel ?? compact(spec.dialogNextText) } };
    }
    return result(s, outcome, { kind: 'tap', ...input, sequence: s.actionSequence }, applied);
  }
  function decide(checkpoint, observation) {
    const { now, facts } = observation ?? {};
    const tickAt = observation?.tickAt ?? now;
    valid(checkpoint, now);
    const s = copy(checkpoint);
    if (s.done) return result(s, 'done');
    if (tickAt < s.nextReadAt) return result(s);
    s.nextReadAt = tickAt + 1200;
    // Elapsed normal waiting cannot establish completion or failure. Keep
    // the existing phase, evidence counters and cadence for the next event.
    let request;
    function observe(mode) {
      const frame = facts?.frames?.[mode];
      if (!frame) { request = { kind: 'read-visual', ruleRef: mode }; return undefined; }
      if (frame.failed) {
        if (frame.captureError) s.captureError = String(frame.captureError).slice(0, 160);
        return undefined;
      }
      if (frame.ownerValid !== true) return undefined;
      if (!(mode === 'ad' && observation.entryAdObserved)) {
        s.observationCount++;
        if (lines(frame).some(line => compact(line.text) === compact(spec.adBadgeText))) s.badgeCount++;
      }
      return frame;
    }
    const pending = () => result(s, 'waiting', request);
    const fromAd = s.phase === 'ad';
    let first = observe(s.phase === 'entry' || fromAd ? 'ad' : 'dialog');
    if (!first) {
      if (fromAd && facts?.frames?.ad) delete s.openSourceSeen;
      return pending();
    }
    const queries = facts?.queries ?? {};
    function fallbackRequest(frame) {
      if (fallbackEligible(frame, queries) && !facts.frames?.[fallbackId]) {
        request={kind:'read-visual',ruleRef:fallbackId};return true;
      }
      return false;
    }
    if (s.phase === 'entry') {
      if (adBadgeVisible(first)) { s.phase = 'ad'; s.adSeen = true; s.phaseAt = now; s.nextReadAt = 0; return result(s, 'ad'); }
      const dialog = observe('dialog'); if (!dialog) return pending();
      const next = nextTarget(dialog, queries);
      if (next) return tap(s, next, 'next', { phase: 'ad', delay: 500 });
      const resume = observe('resume'); if (!resume) return pending();
      const target = resumeTarget(resume);
      return target ? tap(s, target, 'resume', { phase: 'ad', delay: 500 }) : result(s);
    }
    if (fromAd) {
      const badge = adBadgeVisible(first), ready = hasLine(first, spec.adReadyText), countdown = adCountdownVisible(first);
      if (badge) {
        s.adSeen = true;
        delete s.pendingOpen;
        delete s.openSourceSeen;
      }
      if (s.pendingOpen && !s.adSeen) {
        if (ready || countdown) {
          delete s.openSourceSeen;
          return result(s);
        }
        const kind = s.pendingOpen.kind;
        const mode = kind === 'next' ? 'dialog' : 'resume';
        const frame = observe(mode);
        if (!frame) {
          if (facts.frames[mode]) delete s.openSourceSeen;
          return pending();
        }
        const target = kind === 'next' ? nextTarget(frame, queries) : resumeTarget(frame);
        const label = target?.openLabel ?? compact(spec.dialogNextText);
        if (!target || label !== s.pendingOpen.label) {
          delete s.openSourceSeen;
          return result(s);
        }
        if (s.openSourceSeen) return tap(s, target, kind, { phase: 'ad', delay: 500 });
        s.openSourceSeen = true;
        return result(s);
      }
      if (badge && ready && !countdown) s.adReadySeen = true;
      if (enhanced && s.adSeen === true && !badge && !ready && !countdown) {
        // The app can close a witnessed ad by itself. Only the existing owned
        // reward, resume or terminal proof can confirm that transition.
        first = observe('dialog');
        if (!first) return pending();
      } else {
        if (ready) s.readyCount++;
        if (countdown) s.countdownCount++;
        if (queries['close-image']?.matched) s.closeImageCount++;
        if (fallbackRequest(first)) return pending();
        const target = closeTarget(first, queries);
        return target ? tap(s, target, 'closed', { phase: 'dialog', delay: 500,
          fallbackClose:target.fallback===true,
          ...(enhanced ? { closePending: true, closeRetries: 0 } : { adsClosedDelta: 1 }) }) : result(s);
      }
    }
    if (lines(first).some(line => spec.terminalTexts.some(word => compact(line.text).includes(compact(word))))) {
      if (enhanced && (s.closePending || fromAd)) { s.adsClosed++; s.closePending = false; }
      s.done = true; s.reason = '已看到工具包声明的结束标记'; return result(s, 'done');
    }
    if (!enhanced) {
      if (s.adsClosed >= spec.maxAds) {
        s.done = true; s.reason = '达到工具包循环上限，停止防止重复广告'; return result(s, 'done');
      }
      const next = nextTarget(first, queries);
      if (next) return tap(s, next, 'next', { phase: 'ad', delay: 500 });
      const frame = observe('resume'); if (!frame) return pending();
      const resume = resumeTarget(frame);
      return resume ? tap(s, resume, 'resume', { phase: 'ad', delay: 500 }) : result(s);
    }
    const next = nextTarget(first, queries);
    let pendingAd;
    if (!fromAd && !next && s.closePending && (s.fallbackClose || s.recheckClosePoint)) {
      pendingAd=observe('ad');if(!pendingAd)return pending();
      if(fallbackRequest(pendingAd))return pending();
      const close=closeTarget(pendingAd,queries);
      if(close){
        return tap(s,close,'retryClose',{delay:500,closeRetriesDelta:1});
      }
      if(fallbackEligible(pendingAd,queries)&&facts.frames?.[fallbackId])return result(s);
    }
    let resume;
    if (!next) { const frame = observe('resume'); if (!frame) return pending(); resume = resumeTarget(frame); }
    if (!fromAd && !next && !resume && s.closePending) {
      const ad = pendingAd ?? observe('ad'); if (!ad) return pending();
      // The visual selector may already have the declared fallback point
      // from this ad crop. Dialog and resume still have their original priority.
      const close = closeTarget(ad, queries);
      if (close) {
        return tap(s, close, 'retryClose', { delay: 500, closeRetriesDelta: 1 });
      }
      if (!pendingAd && fallbackEligible(ad, queries)) {
        s.recheckClosePoint = true;
        s.nextReadAt = now;
        return result(s);
      }
    }
    if (!next && !resume) return result(s);
    if (s.closePending || fromAd && (next || s.adReadySeen === true)) {
      // The current reward is already proven, independently of opening the
      // next ad. A later attempt must resume on this side of the transition.
      s.adsClosed++;
      s.closePending = false;
      s.phase = 'dialog';
    }
    if (s.adsClosed >= spec.maxAds) {
      s.done = true; s.reason = '达到工具包循环上限，停止防止重复广告'; return result(s, 'done');
    }
    return tap(s, next ?? resume, next ? 'next' : 'resume', { phase: 'ad', delay: 500 });
  }
  function commit(decision, receipt) {
    if (!decision.intent || decision.intent.kind !== 'tap' || !receipt ||
      !['applied', 'unknown', 'rejected'].includes(receipt.status) || receipt.sequence !== decision.intent.sequence ||
      !Number.isSafeInteger(receipt.at) || receipt.at < 0) throw Error('invalid-reward-video-receipt');
    const s = copy(decision.checkpoint);
    if (receipt.status !== 'applied') return { status: 'paused', checkpoint: s, outcome: 'waiting',
      reason: 'input-' + receipt.status };
    delete s.recheckClosePoint;
    const applied = decision.applied;
    if (applied.phase) s.phase = applied.phase;
    if (applied.phase === 'ad') {
      s.adSeen = false;
      s.adReadySeen = false;
      s.pendingOpen = applied.pendingOpen;
      delete s.openSourceSeen;
    }
    s.phaseAt = receipt.at; s.nextReadAt = receipt.at + applied.delay;
    if (applied.closePending !== undefined) s.closePending = applied.closePending;
    if (applied.closeRetries !== undefined) s.closeRetries = applied.closeRetries;
    if (applied.fallbackClose !== undefined) s.fallbackClose = applied.fallbackClose;
    s.closeRetries += applied.closeRetriesDelta ?? 0;
    s.adsClosed += applied.adsClosedDelta ?? 0;
    s.actionSequence++;
    return result(s, decision.outcome);
  }
  return { initial, decide, commit, closeTarget, nextTarget, resumeTarget,
    entryAdVisible: frame => frame?.ownerValid === true && adBadgeVisible(frame) &&
      (hasLine(frame, spec.adReadyText) || adCountdownVisible(frame)),
    progress: s => s.phase === 'ad' ? '广告等待中' : s.phase === 'dialog' ? '返回任务页' : '检查奖励入口' };
})
};
const __quietstartRewardSpec={"maxAds":300,"adBadgeText":"广告","adReadyText":"领取成功","adCloseMarks":["×","✕","X"],"entryRecoveryOnAd":true,"adReadRegion":[0.02,0,0.98,0.1],"adCloseRegion":[0.88,0,0.95,0.09],"dialogContextText":"再看","dialogNextText":"领取奖励","dialogReadRegion":[0.13,0.27,0.87,0.66],"dialogButtonRegion":[0.2,0.5,0.8,0.6],"resumeContextText":"再看","resumeNextText":"解锁","resumeAlternateTexts":["继续观看"],"resumeReadRegion":[0.02,0.2,0.98,0.99],"resumeButtonRegion":[0.2,0.48,0.98,0.99],"terminalTexts":["已全部领取","暂无更多奖励","当前已解锁30天"]};
// The original reward-video policy runs here. The native bridge supplies only
// declared observations/projections, fresh references and durable receipts.
const rewardPolicyOriginal = __quietstartKits.rewardVideo({...__quietstartRewardSpec,closeFallbackQuery:'ad-close-point'});
const copy = value => JSON.parse(JSON.stringify(value));
function message(state) {
  return state.done ? state.reason + '；已完成广告 ' + state.adsClosed + ' 条' :
    '已关闭广告 ' + state.adsClosed + ' 条' +
    (state.maxAdsLimit < __quietstartRewardSpec.maxAds ? ' / 本轮目标 ' + state.maxAdsLimit + ' 条' : '') +
    ' · ' + rewardPolicyOriginal.progress(state);
}
function output(state, now, outcome) {
  return { status: state.done ? 'complete' : 'waiting', checkpoint: { policy: state },
    ...(state.done ? {} : { next: { at: Math.max(now, state.nextReadAt) } }),
    successful: false, outcome, message: message(state) };
}
async function __quietstartConfiguredOriginalEvent(ctx, event) {
  const fields = typeof __quietstartConfiguredControls === 'object' ? __quietstartConfiguredControls.video : undefined;
  const config = fields ? await ctx.config.read() : {};
  const maxAds = fields && config[fields.maxAdsKey] !== undefined ? config[fields.maxAdsKey] : __quietstartRewardSpec.maxAds;
  if (!Number.isSafeInteger(maxAds) || maxAds < 1 || maxAds > __quietstartRewardSpec.maxAds) throw Error('invalid-video-task-limit');
  const rewardPolicy = fields ? __quietstartKits.rewardVideo({...__quietstartRewardSpec,maxAds,closeFallbackQuery:'ad-close-point'}) : rewardPolicyOriginal;
  if (event?.kind === 'entry-probe') {
    const frame = await ctx.observe.snapshot({ fields: ['queries'], reason: '核对已声明的奖励广告入口' });
    const visual = frame.ownerValid ? await ctx.vision.ocr({ ruleRef: 'ad' }) : undefined;
    const eligible = frame.ownerValid === true && rewardPolicy.entryAdVisible(visual);
    return { status: 'complete', checkpoint: { policy: null }, eligible,
      message: eligible ? '已确认声明的奖励广告页' : '尚未确认声明的奖励广告页' };
  }
  if (event?.kind !== 'tick' || !Number.isSafeInteger(event.actionSequence) || event.actionSequence < 0) {
    throw Error('invalid-reward-video-event');
  }
  const tickAt = await ctx.clock.now();
  let before = ctx.checkpoint?.policy;
  if (before == null) { before = rewardPolicy.initial(tickAt); before.actionSequence = event.actionSequence; }
  else before=copy(before);
  before.maxAdsLimit=maxAds;
  if (!before.done && tickAt < before.nextReadAt) return output(before, tickAt, 'waiting');
  const due = rewardPolicy.decide(before, { now: tickAt, tickAt, facts: {} });
  if (due.checkpoint.done) return output(due.checkpoint, tickAt, due.outcome);
  let decision = due;
  let frames = {};
  while (decision.intent?.kind === 'read-visual') {
    const id = decision.intent.ruleRef;
    if (!['ad', 'dialog', 'resume'].includes(id) || frames[id]) throw Error('invalid-reward-visual-request');
    const selected = await ctx.actions.select({
      queryRefs: ['close-image', 'dialog-text-exists'],
      visualRefs: id === 'ad' ? ['ad', 'ad-close-point'] : [id],
      input: { before, frames, id, tickAt, maxAds },
      idempotencyKey: ctx.run.id + '/' + before.actionSequence
    });
    const { receipt, value } = selected;
    if (receipt.consumed && !value?.decision?.intent) throw Error('reward-receipt-without-selection');
    if (receipt.status === 'not-dispatched') {
      const now = await ctx.clock.now(), observed = value?.decision?.checkpoint;
      const retry = observed?.phase === 'dialog' && observed.adsClosed === before.adsClosed + 1 ?
        observed : value?.entered ?? before;
      if (retry.pendingOpen) delete retry.openSourceSeen;
      if (value?.decision?.checkpoint?.phase === 'ad' && value.decision.checkpoint.adReadySeen === true) {
        retry.adSeen = true;
        retry.adReadySeen = true;
      }
      retry.nextReadAt = Math.max(retry.nextReadAt, due.checkpoint.nextReadAt);
      return output(retry, now, 'waiting');
    }
    if (value.diagnostic && value.diagnostic !== before.adDiagnostic) {
      before.adDiagnostic = value.diagnostic;
      await ctx.log.write({ message: '广告关闭诊断 ' + value.diagnostic });
    }
    decision = receipt.status === 'no-input' ? value.decision : rewardPolicy.commit(value.decision, { ...receipt,
      status: receipt.status === 'already-applied' ? 'applied' : receipt.status });
    frames = value.frames ?? frames;
  }
  if (decision.status === 'paused') throw Error(decision.reason || 'reward-input-unconfirmed');
  const result = output(decision.checkpoint, await ctx.clock.now(), decision.outcome);
  if (decision.outcome !== 'waiting') await ctx.ui.publish({ kind: 'capsule', message: result.message,
    stopped: result.status === 'complete' });
  return result;
}

const __quietstartConfiguredControls={"tasks":[],"stages":[],"safeFinish":true,"video":{"maxAdsKey":"video.maxAds"}};
// Author-side settings adapter. This never changes target declarations, input
// permissions, original checkpoints, or an application's completion conditions.
export async function onEvent(ctx, event) {
  if (event?.kind === 'input-select') return selectReward(event);
  const config = await ctx.config.read();
  const controls = typeof __quietstartConfiguredControls === 'object' ? __quietstartConfiguredControls : {};
  if (controls.tasks?.length) {
    const disabled = new Set(controls.tasks.filter(task => config[task.key] === false).map(task => task.id));
    // Local settings only subtract from the host's current authorized list.
    // Missing native lists retain the original adapter's fail-closed behavior.
    if (Array.isArray(event?.enabledTaskIds)) {
      const selected = event.enabledTaskIds.filter(id => !disabled.has(id));
      if (controls.supportTasks?.length && controls.tasks.filter(task => !controls.supportTasks.includes(task.id)).every(task => disabled.has(task.id))) selected.splice(0);
      event = controls.safeFinish ? { ...event, selectedTaskIds: selected } : { ...event, enabledTaskIds: selected };
    }
    else if (disabled.size === controls.tasks.length) event = { ...event, enabledTaskIds: [] };
  }
  const prefix = typeof config.progressPrefix === 'string' ? config.progressPrefix.trim() : '';
  const message = text => prefix && typeof text === 'string' && text ? (prefix + ' · ' + text).slice(0, 500) : text;
  const port = { ...ctx, config: { ...ctx.config, read: async () => config },
    ...(prefix && ctx.ui?.publish ? { ui: { ...ctx.ui,
      publish: item => ctx.ui.publish({ ...item, message: message(item.message) }) } } : {}) };
  const result = await __quietstartConfiguredOriginalEvent(port, event);
  if (prefix && typeof result?.message === 'string') result.message = message(result.message);
  const delay = config.nextActionDelayMs;
  if (result?.status === 'waiting' && result.next && Number.isSafeInteger(delay) && delay > 0) {
    result.next = { ...result.next, at: Math.max(result.next.at, (await ctx.clock.now()) + delay) };
  }
  return result;
}

// The host acquired these declared facts inside this single input request.
// Only the signed policy chooses an action. Previous crops supply context;
// the host accepts a target and evidence only from this request's capture.
function selectReward(event) {
  const { before, frames, id, tickAt, maxAds } = event.input;
  const queries = event.observation.queries;
  const current = queries[id];
  frames[id] = current;
  let diagnostic;
  if (id === 'ad') {
    frames['ad-close-point'] = queries['ad-close-point'];
    diagnostic = JSON.stringify({ native: queries['close-image']?.matched === true,
      lines: (current.lines || []).slice(0, 6).map(line => [String(line.text || '').slice(0, 24), Object.keys(line.targets || {})]) }).slice(0, 210);
    before.adDiagnostic = diagnostic;
  }
  const policy = __quietstartKits.rewardVideo({ ...__quietstartRewardSpec, maxAds, closeFallbackQuery: 'ad-close-point' });
  const facts = { queries, frames };
  const observation = { now: event.at, tickAt, facts };
  let decision = policy.decide(before, observation), entered;
  if (before.phase === 'entry' && decision.outcome === 'ad') {
    const close = policy.decide(decision.checkpoint, { ...observation, entryAdObserved: true });
    if (close.intent?.kind === 'tap') { entered = decision.checkpoint; decision = close; }
  }
  const intent = decision.intent;
  if (intent?.kind !== 'tap') return { action: null, value: { decision, frames, diagnostic } };
  if (intent.sequence !== before.actionSequence) throw Error('invalid-reward-selection-sequence');
  return { action: { kind: 'tap', targetRef: intent.targetRef,
    ...(intent.evidenceRefs ? { evidenceRefs: intent.evidenceRefs } : {}) }, value: { decision, entered, diagnostic } };
}

export function migrate(input) {
  if (input?.from !== 'legacy-reward-video/1') throw Error('unsupported-reward-video-migration');
  const checkpoint = input.checkpoint ?? { policy: null };
  if (!checkpoint || typeof checkpoint !== 'object' || Array.isArray(checkpoint) ||
    Object.keys(checkpoint).some(key => key !== 'policy') || checkpoint.policy !== null &&
    (typeof checkpoint.policy !== 'object' || Array.isArray(checkpoint.policy))) throw Error('invalid-reward-video-adapter-state');
  return { schema: 1, checkpoint };
}
